from solution import reconcile
from itertools import permutations

class OnePass:
    def __init__(self, values):
        self.values = values
        self.used = False
    def __iter__(self):
        assert not self.used
        self.used = True
        yield from self.values

assert reconcile(OnePass([])) == {}
assert reconcile(OnePass([
    {'entity': 'a', 'version': 3, 'deleted': True},
    {'entity': 'a', 'version': 2, 'payload': 'stale'},
])) == {}
assert reconcile([
    {'entity': 'a', 'version': 3, 'deleted': True},
    {'entity': 'a', 'version': 4, 'payload': None},
]) == {'a': None}
base = [
    {'entity': 'a', 'version': 0, 'payload': False},
    {'entity': 'a', 'version': 2, 'payload': []},
    {'entity': 'a', 'version': 2, 'deleted': True},
    {'entity': 'b', 'version': 1, 'payload': 0},
]
for events in permutations(base):
    winners = {}
    for event in events:
        if event['entity'] not in winners or event['version'] >= winners[event['entity']]['version']:
            winners[event['entity']] = event
    expected = {key: event['payload'] for key, event in winners.items() if not event.get('deleted', False)}
    assert reconcile(OnePass(events)) == expected
invalid = [None, [], 'event', {},
    {'entity': '', 'version': 0, 'payload': None},
    {'entity': 1, 'version': 0, 'payload': None},
    {'entity': 'a', 'payload': None},
    *[{'entity': 'a', 'version': v, 'payload': None} for v in [True, False, -1, 1.0, '1', None]],
    *[{'entity': 'a', 'version': 0, 'deleted': d, 'payload': None} for d in [None, 0, 1, 'false', []]],
    {'entity': 'a', 'version': 0},
]
for event in invalid:
    try:
        reconcile(iter([{'entity': 'a', 'version': 100, 'payload': 'winner'}, event]))
    except ValueError:
        pass
    else:
        raise AssertionError(('accepted invalid event', event))
payload = {'nested': [1, {'x': []}]}
events = [{'entity': ' a ', 'version': 0, 'payload': payload, 'ignored': object()},
          {'entity': 'A', 'version': 0, 'payload': ''},
          {'entity': ' ', 'version': 0, 'payload': None}]
result = reconcile(OnePass(events))
assert set(result) == {' a ', 'A', ' '}
result[' a ']['nested'][1]['x'].append(2)
assert payload['nested'][1]['x'] == []
payload['nested'].append(3)
assert len(result[' a ']['nested']) == 2
assert events[0]['payload'] is payload
cyclic = []
cyclic.append(cyclic)
copied = reconcile([{'entity': 'cycle', 'version': 0, 'payload': cyclic}])['cycle']
assert copied is not cyclic and copied[0] is copied
print('Passed: 24 order permutations, 19 invalid events (including stale), one-pass input, tombstones/revival, exact identifiers, falsy payloads, nested isolation, and cyclic payloads.')
PY

git diff --check
